var useCartStore = create()(persist((set, get) => ({
	items: [],
	savedForLater: [],
	totalItems: 0,
	subtotal: 0,
	addItem: (productId, quantity = 1) => {
		set((state) => {
			const existing = state.items.find((i) => i.productId === productId);
			let items;
			if (existing) items = state.items.map((i) => i.productId === productId ? {
				...i,
				quantity: i.quantity + quantity
			} : i);
			else items = [...state.items, {
				productId,
				quantity
			}];
			return {
				items,
				totalItems: items.reduce((sum, i) => sum + i.quantity, 0),
				subtotal: items.reduce((sum, i) => sum + i.product?.price * i.quantity || 0, 0)
			};
		});
	},
	updateQuantity: (productId, quantity) => {
		set((state) => {
			if (quantity <= 0) {
				const items = state.items.filter((i) => i.productId !== productId);
				return {
					items,
					totalItems: items.reduce((sum, i) => sum + i.quantity, 0),
					subtotal: items.reduce((sum, i) => sum + i.product?.price * i.quantity || 0, 0)
				};
			}
			const items = state.items.map((i) => i.productId === productId ? {
				...i,
				quantity
			} : i);
			return {
				items,
				totalItems: items.reduce((sum, i) => sum + i.quantity, 0),
				subtotal: items.reduce((sum, i) => sum + i.product?.price * i.quantity || 0, 0)
			};
		});
	},
	removeItem: (productId) => {
		set((state) => {
			const items = state.items.filter((i) => i.productId !== productId);
			return {
				items,
				totalItems: items.reduce((sum, i) => sum + i.quantity, 0),
				subtotal: items.reduce((sum, i) => sum + i.product?.price * i.quantity || 0, 0)
			};
		});
	},
	clearCart: () => set({
		items: [],
		totalItems: 0,
		subtotal: 0
	}),
	itemCount: () => get().items.length,
	saveForLater: (productId) => {
		const item = get().items.find((i) => i.productId === productId);
		if (!item) return;
		const saved = {
			productId: item.productId,
			quantity: item.quantity
		};
		set((state) => {
			const items = state.items.filter((i) => i.productId !== productId);
			return {
				items,
				savedForLater: [...state.savedForLater, saved],
				totalItems: items.reduce((sum, i) => sum + i.quantity, 0),
				subtotal: items.reduce((sum, i) => sum + i.product?.price * i.quantity || 0, 0)
			};
		});
	},
	moveToCart: (productId) => {
		const saved = get().savedForLater.find((i) => i.productId === productId);
		if (!saved) return;
		set((state) => {
			const existing = state.items.find((i) => i.productId === productId);
			let items;
			if (existing) items = state.items.map((i) => i.productId === productId ? {
				...i,
				quantity: i.quantity + saved.quantity
			} : i);
			else items = [...state.items, {
				productId: saved.productId,
				quantity: saved.quantity
			}];
			return {
				items,
				savedForLater: state.savedForLater.filter((i) => i.productId !== productId),
				totalItems: items.reduce((sum, i) => sum + i.quantity, 0),
				subtotal: items.reduce((sum, i) => sum + i.product?.price * i.quantity || 0, 0)
			};
		});
	},
	removeSaved: (productId) => {
		set((state) => ({ savedForLater: state.savedForLater.filter((i) => i.productId !== productId) }));
	}
}), {
	name: "damorex-cart",
	merge: (persisted, current) => ({
		...current,
		...persisted,
		savedForLater: persisted?.savedForLater ?? []
	})
}));
